package com.mailservice.graphql

import graphql.ExecutionInput
import graphql.GraphQL
import graphql.schema.idl.RuntimeWiring
import graphql.schema.idl.SchemaGenerator
import graphql.schema.idl.SchemaParser
import graphql.schema.idl.TypeDefinitionRegistry
import org.slf4j.LoggerFactory
import java.time.Instant
import java.util.UUID

data class AuditEntry(
    val id: String = UUID.randomUUID().toString(),
    val timestamp: Instant = Instant.now(),
    val action: String,
    val actor: String,
    val details: String,
    val status: String
)

class AuditLogger {
    private val log = LoggerFactory.getLogger(AuditLogger::class.java)
    private val entries = mutableListOf<AuditEntry>()

    fun logAction(action: String, actor: String, details: String, status: String): AuditEntry {
        val entry = AuditEntry(action = action, actor = actor, details = details, status = status)
        entries.add(entry)
        log.info("Audit: [${entry.id}] $action by $actor - $status")
        return entry
    }

    fun queryEntries(filterExpression: String?): List<AuditEntry> {
        if (filterExpression.isNullOrBlank()) return entries.toList()
        return entries.filter { entry ->
            evaluateFilter(entry, filterExpression)
        }
    }

    private fun evaluateFilter(entry: AuditEntry, expr: String): Boolean {
        val parts = expr.split("=", limit = 2)
        if (parts.size != 2) return true
        val field = parts[0].trim()
        val value = parts[1].trim().removeSurrounding("\"")
        return when (field) {
            "action" -> entry.action == value
            "actor" -> entry.actor == value
            "status" -> entry.status == value
            else -> true
        }
    }
}

class EmailService(private val auditLogger: AuditLogger) {
    private val log = LoggerFactory.getLogger(EmailService::class.java)

    fun sendEmail(to: String, subject: String, body: String, senderContext: SenderContext): Map<String, Any> {
        validateRecipient(to)
        val sanitizedSubject = sanitizeContent(subject)
        val sanitizedBody = sanitizeContent(body)

        log.info("Sending email to $to with subject: $sanitizedSubject")

        auditLogger.logAction(
            action = "SEND_EMAIL",
            actor = senderContext.userId,
            details = "to=$to, subject=$sanitizedSubject",
            status = "SUCCESS"
        )

        return mapOf(
            "messageId" to UUID.randomUUID().toString(),
            "status" to "SENT",
            "recipient" to to
        )
    }

    private fun validateRecipient(email: String) {
        require(email.matches(Regex("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"))) {
            "Invalid email address"
        }
    }

    private fun sanitizeContent(input: String): String {
        return input.replace(Regex("[<>\"'&]"), "")
    }
}

data class SenderContext(val userId: String, val roles: Set<String>)

class GraphQLEmailEndpoint(private val emailService: EmailService, private val auditLogger: AuditLogger) {

    private val schema = """
        type Query {
            auditLog(filter: String): [AuditEntry!]!
            healthCheck: String!
        }
        type Mutation {
            sendEmail(to: String!, subject: String!, body: String!): EmailResult!
        }
        type AuditEntry {
            id: String!
            timestamp: String!
            action: String!
            actor: String!
            details: String!
            status: String!
        }
        type EmailResult {
            messageId: String!
            status: String!
            recipient: String!
        }
    """.trimIndent()

    private val graphQL: GraphQL

    init {
        val typeRegistry: TypeDefinitionRegistry = SchemaParser().parse(schema)
        val runtimeWiring = RuntimeWiring.newRuntimeWiring()
            .type("Query") { builder ->
                builder.dataFetcher("auditLog") { env ->
                    val filter = env.getArgument<String?>("filter")
                    val context = env.graphQlContext.get<SenderContext>("senderContext")
                    requireAdminRole(context)
                    auditLogger.queryEntries(filter)
                }
                builder.dataFetcher("healthCheck") { "OK" }
            }
            .type("Mutation") { builder ->
                builder.dataFetcher("sendEmail") { env ->
                    val to = env.getArgument<String>("to")
                    val subject = env.getArgument<String>("subject")
                    val body = env.getArgument<String>("body")
                    val context = env.graphQlContext.get<SenderContext>("senderContext")
                    emailService.sendEmail(to, subject, body, context)
                }
            }
            .build()

        graphQL = GraphQL.newGraphQL(SchemaGenerator().makeExecutableSchema(typeRegistry, runtimeWiring)).build()
    }

    fun execute(query: String, variables: Map<String, Any>?, senderContext: SenderContext): Map<String, Any?> {
        val executionInput = buildExecutionInput(query, variables, senderContext)
        val result = graphQL.execute(executionInput)
        return mapOf(
            "data" to result.getData(),
            "errors" to result.errors.map { it.message }
        )
    }

    private fun buildExecutionInput(query: String, variables: Map<String, Any>?, context: SenderContext): ExecutionInput {
        val builder = ExecutionInput.newExecutionInput()
            .query(query)
            .graphQLContext(mapOf("senderContext" to context))

        if (variables != null) {
            builder.variables(variables)
        }
        return builder.build()
    }

    private fun requireAdminRole(context: SenderContext) {
        require(context.roles.contains("ADMIN")) { "Insufficient permissions" }
    }
}

class RequestHandler(private val endpoint: GraphQLEmailEndpoint) {

    fun handleRequest(rawBody: String, headers: Map<String, String>): Map<String, Any?> {
        val senderContext = extractSenderContext(headers)
        val (query, variables, operationName) = parseGraphQLRequest(rawBody)

        val introspectionBlocked = query.contains("__schema") || query.contains("__type")
        if (introspectionBlocked) {
            return mapOf("errors" to listOf("Introspection disabled"))
        }

        return endpoint.execute(query, variables, senderContext)
    }

    private fun extractSenderContext(headers: Map<String, String>): SenderContext {
        val userId = headers["X-User-Id"] ?: "anonymous"
        val roles = headers["X-User-Roles"]?.split(",")?.toSet() ?: emptySet()
        return SenderContext(userId = userId, roles = roles)
    }

    private fun parseGraphQLRequest(body: String): Triple<String, Map<String, Any>?, String?> {
        val jsonMap = parseSimpleJson(body)
        val query = jsonMap["query"] as? String ?: throw IllegalArgumentException("Missing query")
        @Suppress("UNCHECKED_CAST")
        val variables = jsonMap["variables"] as? Map<String, Any>
        val operationName = jsonMap["operationName"] as? String
        return Triple(query, variables, operationName)
    }

    private fun parseSimpleJson(json: String): Map<String, Any?> {
        // Simplified JSON parsing for demonstration
        val result = mutableMapOf<String, Any?>()
        val content = json.trim().removeSurrounding("{", "}")
        val pairs = content.split(",(?=\\s*\")".toRegex())
        for (pair in pairs) {
            val colonIdx = pair.indexOf(':')
            if (colonIdx == -1) continue
            val key = pair.substring(0, colonIdx).trim().removeSurrounding("\"")
            val value = pair.substring(colonIdx + 1).trim()
            result[key] = when {
                value == "null" -> null
                value.startsWith("\"") -> value.removeSurrounding("\"")
                value.startsWith("{") -> value // nested objects kept as string for simplicity
                else -> value
            }
        }
        return result
    }
}

// Batch processing endpoint for scheduled reports
class BatchAuditReporter(private val auditLogger: AuditLogger) {

    fun generateReport(criteria: Map<String, String>, requestingUser: SenderContext): String {
        requireReportPermission(requestingUser)

        val filterChain = criteria.entries.joinToString(" AND ") { (k, v) ->
            "$k=\"$v\""
        }

        // The filter chain is passed directly - each segment evaluated independently
        val results = criteria.entries.flatMap { (key, value) ->
            auditLogger.queryEntries("$key=\"$value\"")
        }.distinctBy { it.id }

        return buildReportOutput(results, filterChain)
    }

    fun generateReportFromTemplate(templateName: String, overrides: Map<String, String>, user: SenderContext): String {
        val baseFilters = getTemplateFilters(templateName)
        val mergedFilters = baseFilters + overrides
        return generateReport(mergedFilters, user)
    }

    private fun getTemplateFilters(name: String): Map<String, String> {
        return when (name) {
            "daily_sends" -> mapOf("action" to "SEND_EMAIL", "status" to "SUCCESS")
            "failures" -> mapOf("status" to "FAILURE")
            "all_activity" -> emptyMap()
            else -> throw IllegalArgumentException("Unknown template: $name")
        }
    }

    private fun requireReportPermission(context: SenderContext) {
        require(context.roles.contains("ADMIN") || context.roles.contains("AUDITOR")) {
            "Report generation requires ADMIN or AUDITOR role"
        }
    }

    private fun buildReportOutput(entries: List<AuditEntry>, filterDescription: String): String {
        val sb = StringBuilder()
        sb.appendLine("=== Audit Report ===")
        sb.appendLine("Filter: $filterDescription")
        sb.appendLine("Total entries: ${entries.size}")
        sb.appendLine("---")
        entries.forEach { entry ->
            sb.appendLine("[${entry.timestamp}] ${entry.action} by ${entry.actor}: ${entry.details} (${entry.status})")
        }
        return sb.toString()
    }
}
